===== lib/prisma.ts =====
// design/001_boards.md § 実装方針
import "dotenv/config";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaClient } from "../generated/prisma/client";

const globalForPrisma = globalThis as unknown as {
  prisma?: PrismaClient;
};

function createPrisma(): PrismaClient {
  const raw = process.env.DATABASE_URL ?? "file:./dev.db";
  const url = raw === "file:./dev.db" ? "file:./prisma/dev.db" : raw;
  const adapter = new PrismaBetterSqlite3({ url });
  return new PrismaClient({ adapter });
}

export const prisma: PrismaClient = globalForPrisma.prisma ?? createPrisma();

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

===== lib/errors.ts =====
// spec/000_shared_rules.md § HTTP ステータスコードとエラーレスポンス
import { NextResponse } from "next/server";

type ErrorCode =
  | "UNAUTHORIZED"
  | "FORBIDDEN"
  | "NOT_FOUND"
  | "VALIDATION_ERROR"
  | "INTERNAL_ERROR";

type ErrorBody = {
  error: {
    code: ErrorCode;
    message: string;
    details?: Record<string, string>;
  };
};

function build(
  code: ErrorCode,
  message: string,
  status: number,
  details?: Record<string, string>,
) {
  const body: ErrorBody = { error: { code, message, ...(details ? { details } : {}) } };
  return NextResponse.json(body, { status });
}

export const unauthorized = () =>
  build("UNAUTHORIZED", "ログインが必要です", 401);
export const forbidden = () =>
  build("FORBIDDEN", "この操作を実行する権限がありません", 403);
export const notFound = (message = "対象のリソースが見つかりません") =>
  build("NOT_FOUND", message, 404);
export const validationError = (
  message: string,
  details?: Record<string, string>,
) => build("VALIDATION_ERROR", message, 422, details);
export const internalError = (message = "予期しないエラーが発生しました") =>
  build("INTERNAL_ERROR", message, 500);

===== lib/validation/text.ts =====
// design/001_boards.md § 実装方針、design/003_cards.md § 実装方針
// title は trim(前後の半角・全角空白、タブ、改行) 後の長さで検証する

const TRIM_PATTERN = /^[\s　]+|[\s　]+$/g;

export function normalize(raw: unknown): string {
  if (typeof raw !== "string") return "";
  return raw.replace(TRIM_PATTERN, "");
}

export type ValidationErr = { ok: false; reason: "required" | "too_long" | "invalid_type" };
export type ValidationOk = { ok: true; value: string };
export type ValidationResult = ValidationOk | ValidationErr;

export function validateTitle(raw: unknown, max: number): ValidationResult {
  if (raw !== undefined && typeof raw !== "string") {
    return { ok: false, reason: "invalid_type" };
  }
  const value = normalize(raw);
  if (value.length === 0) return { ok: false, reason: "required" };
  if (value.length > max) return { ok: false, reason: "too_long" };
  return { ok: true, value };
}

export function validateDescription(raw: unknown, max: number): ValidationResult {
  if (raw !== undefined && raw !== null && typeof raw !== "string") {
    return { ok: false, reason: "invalid_type" };
  }
  const value = typeof raw === "string" ? raw : "";
  if (value.length > max) return { ok: false, reason: "too_long" };
  return { ok: true, value };
}

===== lib/audit/log.ts =====
// design/001_boards.md § 監査ログ
type Payload = Record<string, unknown>;

export function auditLog(action: string, payload: Payload) {
  const record = {
    ts: new Date().toISOString(),
    action,
    ...payload,
  };
  console.info(JSON.stringify(record));
}

===== lib/auth/currentUser.ts =====
// spec/000_shared_rules.md § 認証の前提
// 本章 02 セクションでは、開発用の固定ユーザーを1件用意して返す
import { prisma } from "@/lib/prisma";

const DEV_USER_EMAIL = "dev@example.com";

export type CurrentUser = { id: string; email: string };

export async function currentUser(): Promise<CurrentUser | null> {
  const existing = await prisma.user.findUnique({
    where: { email: DEV_USER_EMAIL },
    select: { id: true, email: true },
  });
  if (existing) return existing;
  const created = await prisma.user.create({
    data: { email: DEV_USER_EMAIL },
    select: { id: true, email: true },
  });
  return created;
}

===== lib/auth/requireBoardRole.ts =====
// design/001_boards.md § 権限チェックの配置
// 「認証 → 対象存在 → 権限 → 入力検証」の順で判定するためのヘルパー
import { prisma } from "@/lib/prisma";

export type BoardRole = "owner" | "member" | "viewer";

const ROLE_RANK: Record<BoardRole, number> = { viewer: 0, member: 1, owner: 2 };

export type BoardAccessResult =
  | { kind: "ok"; role: BoardRole }
  | { kind: "not_found" }
  | { kind: "forbidden" };

export async function checkBoardAccess(
  userId: string,
  boardId: string,
  minRole: BoardRole,
): Promise<BoardAccessResult> {
  const board = await prisma.board.findUnique({
    where: { id: boardId },
    select: { id: true },
  });
  if (!board) return { kind: "not_found" };

  const membership = await prisma.boardMembership.findUnique({
    where: { boardId_userId: { boardId, userId } },
    select: { role: true },
  });
  if (!membership) return { kind: "not_found" };

  if (ROLE_RANK[membership.role] < ROLE_RANK[minRole]) {
    return { kind: "forbidden" };
  }
  return { kind: "ok", role: membership.role };
}

