describe("cards", () => {
  it("FR-003/005: title と description の PATCH", async () => {
    const board = await createBoard("u1");
    const listRes = await listsPOST(
      jsonReq(`http://localhost/api/boards/${board.id}/lists`, { title: "L" }),
      boardCtx(board.id),
