}

export function errorLog(requestId: string, error: unknown, status?: number) {
  console.error(
    JSON.stringify({
      ts: new Date().toISOString(),
      level: "error",
      requestId,
      status,
      message: error instanceof Error ? error.message : String(error),
    }),
  );
}

