import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";

type List = { id: string; title: string };

export default function ListHeader({ list }: { list: List }) {
  const router = useRouter();
  const [editing, setEditing] = useState(false);
  const [title, setTitle] = useState(list.title);
  const [error, setError] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  async function commit() {
    setError(null);
    if (title === list.title) {
      setEditing(false);
      return;
    }
    const res = await fetch(`/api/lists/${list.id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      setError(body?.error?.message ?? "更新に失敗しました");
      setTitle(list.title);
      return;
    }
    setEditing(false);
    startTransition(() => router.refresh());
  }

  async function remove() {
    if (!confirm(`「${list.title}」を削除します。配下のカードも削除されます。`)) return;
    const res = await fetch(`/api/lists/${list.id}`, { method: "DELETE" });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      setError(body?.error?.message ?? "削除に失敗しました");
      return;
    }
    startTransition(() => router.refresh());
  }

  return (
    <div className="mb-3 flex items-start justify-between gap-2 px-1">
      {editing ? (
        <input
          className="w-full rounded border border-slate-300 px-2 py-1 text-sm font-semibold focus:border-slate-500 focus:outline-none"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              e.currentTarget.blur();
            }
          }}
          autoFocus
        />
      ) : (
        <h2
          className="cursor-text text-sm font-semibold text-slate-800"
          onClick={() => setEditing(true)}
        >
          {list.title}
        </h2>
      )}
      <button
        type="button"
        onClick={remove}
        aria-label="リスト削除"
        className="shrink-0 rounded px-1 text-xs text-slate-400 hover:text-red-600"
      >
        ✕
      </button>
      {error && <p className="text-xs text-red-600">{error}</p>}
    </div>
  );
}

