  return { prisma };
});

let boardsGET: typeof import("@/app/api/boards/route").GET;
let boardsPOST: typeof import("@/app/api/boards/route").POST;
let boardPATCH: typeof import("@/app/api/boards/[boardId]/route").PATCH;
let boardDELETE: typeof import("@/app/api/boards/[boardId]/route").DELETE;
let listsGET: typeof import("@/app/api/boards/[boardId]/lists/route").GET;
let listsPOST: typeof import("@/app/api/boards/[boardId]/lists/route").POST;
let listPATCH: typeof import("@/app/api/lists/[listId]/route").PATCH;
let listDELETE: typeof import("@/app/api/lists/[listId]/route").DELETE;
let cardsGET: typeof import("@/app/api/lists/[listId]/cards/route").GET;
let cardsPOST: typeof import("@/app/api/lists/[listId]/cards/route").POST;
let cardPATCH: typeof import("@/app/api/cards/[cardId]/route").PATCH;
let cardDELETE: typeof import("@/app/api/cards/[cardId]/route").DELETE;

beforeAll(async () => {
  ({ GET: boardsGET, POST: boardsPOST } = await import("@/app/api/boards/route"));
  ({ PATCH: boardPATCH, DELETE: boardDELETE } = await import(
    "@/app/api/boards/[boardId]/route"
  ));
  ({ GET: listsGET, POST: listsPOST } = await import(
    "@/app/api/boards/[boardId]/lists/route"
  ));
  ({ PATCH: listPATCH, DELETE: listDELETE } = await import("@/app/api/lists/[listId]/route"));
  ({ GET: cardsGET, POST: cardsPOST } = await import(
    "@/app/api/lists/[listId]/cards/route"
  ));
  ({ PATCH: cardPATCH, DELETE: cardDELETE } = await import("@/app/api/cards/[cardId]/route"));
});

afterEach(() => {
  boards.length = 0;
  lists.length = 0;
  cards.length = 0;
  seq = 1;
});

function jsonReq(url: string, body: unknown, method: "POST" | "PATCH" = "POST") {
  return new Request(url, {
    method,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  }) as unknown as import("next/server").NextRequest;
}
function bareReq(url: string, method: "GET" | "DELETE" = "GET") {
  return new Request(url, { method }) as unknown as import("next/server").NextRequest;
}
const boardCtx = (boardId: string) => ({ params: Promise.resolve({ boardId }) });
const listCtx = (listId: string) => ({ params: Promise.resolve({ listId }) });
const cardCtx = (cardId: string) => ({ params: Promise.resolve({ cardId }) });

async function createBoard(title = "Board") {
  const res = await boardsPOST(jsonReq("http://localhost/api/boards", { title }));
  return res.json() as Promise<Board>;
}
async function createList(boardId: string, title = "L") {
  const res = await listsPOST(
    jsonReq(`http://localhost/api/boards/${boardId}/lists`, { title }),
    boardCtx(boardId),
  );
  return res.json() as Promise<List>;
}
async function createCard(listId: string, body: object = { title: "C" }) {
  const res = await cardsPOST(
    jsonReq(`http://localhost/api/lists/${listId}/cards`, body),
    listCtx(listId),
  );
  return res;
}

describe("boards", () => {
  it("作成すると order は 0 から連番、一覧は order 昇順で {items}", async () => {
    const a = await createBoard("A");
    const b = await createBoard("B");
    expect(a.order).toBe(0);
    expect(b.order).toBe(1);
    const res = await boardsGET();
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.items.map((x: Board) => x.title)).toEqual(["A", "B"]);
  });

  it("0 件のとき一覧は空配列", async () => {
    const res = await boardsGET();
    const body = await res.json();
    expect(body.items).toEqual([]);
  });

  it("空タイトルは 422、101 文字も 422", async () => {
    for (const bad of ["   ", "a".repeat(101)]) {
      const res = await boardsPOST(jsonReq("http://localhost/api/boards", { title: bad }));
      expect(res.status).toBe(422);
      const body = await res.json();
      expect(body.error.code).toBe("VALIDATION_ERROR");
    }
    expect(boards.length).toBe(0);
  });

  it("100 文字は許可", async () => {
    const res = await boardsPOST(
      jsonReq("http://localhost/api/boards", { title: "a".repeat(100) }),
    );
    expect(res.status).toBe(201);
  });

  it("存在しない ID の PATCH は 404", async () => {
    const res = await boardPATCH(
      jsonReq("http://localhost/api/boards/none", { title: "X" }, "PATCH"),
      boardCtx("none"),
    );
    expect(res.status).toBe(404);
    expect((await res.json()).error.code).toBe("NOT_FOUND");
  });

  it("DELETE は 200 {ok:true}、配下の List/Card も消える", async () => {
    const board = await createBoard();
    const list = await createList(board.id);
    await createCard(list.id);
    const res = await boardDELETE(
      bareReq(`http://localhost/api/boards/${board.id}`, "DELETE"),
      boardCtx(board.id),
    );
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({ ok: true });
    expect(boards.length).toBe(0);
    expect(lists.length).toBe(0);
    expect(cards.length).toBe(0);
  });
});

describe("lists", () => {
  it("存在しない boardId の一覧は 404", async () => {
    const res = await listsGET(
      bareReq("http://localhost/api/boards/none/lists"),
      boardCtx("none"),
    );
    expect(res.status).toBe(404);
  });

  it("作成すると 201・order 採番、名称編集と削除ができる", async () => {
    const board = await createBoard();
    const l0 = await createList(board.id, "L0");
    const l1 = await createList(board.id, "L1");
    expect(l0.order).toBe(0);
    expect(l1.order).toBe(1);

    const patch = await listPATCH(
      jsonReq(`http://localhost/api/lists/${l0.id}`, { title: "renamed" }, "PATCH"),
      listCtx(l0.id),
    );
    expect(patch.status).toBe(200);
    expect((await patch.json()).title).toBe("renamed");

    const del = await listDELETE(
      bareReq(`http://localhost/api/lists/${l1.id}`, "DELETE"),
      listCtx(l1.id),
    );
    expect(del.status).toBe(200);
    expect(lists.length).toBe(1);
  });

  it("order で並び順を更新できる", async () => {
    const board = await createBoard();
    const l = await createList(board.id);
    const res = await listPATCH(
      jsonReq(`http://localhost/api/lists/${l.id}`, { order: 5 }, "PATCH"),
      listCtx(l.id),
    );
    expect(res.status).toBe(200);
    expect((await res.json()).order).toBe(5);
  });

  it("空タイトルは 422、存在しない listId の PATCH は 404", async () => {
    const board = await createBoard();
    const bad = await listsPOST(
      jsonReq(`http://localhost/api/boards/${board.id}/lists`, { title: "" }),
      boardCtx(board.id),
    );
    expect(bad.status).toBe(422);
    const res = await listPATCH(
      jsonReq("http://localhost/api/lists/none", { title: "X" }, "PATCH"),
      listCtx("none"),
    );
    expect(res.status).toBe(404);
  });
});

describe("cards", () => {
  it("description 省略時は空文字、order 採番", async () => {
    const board = await createBoard();
    const list = await createList(board.id);
    const res = await createCard(list.id, { title: "C" });
    expect(res.status).toBe(201);
    const card = await res.json();
    expect(card.description).toBe("");
    expect(card.order).toBe(0);
  });

  it("空 title・201 文字 title・2001 文字 description は 422", async () => {
    const board = await createBoard();
    const list = await createList(board.id);
    for (const bad of ["", "a".repeat(201)]) {
      const res = await createCard(list.id, { title: bad });
      expect(res.status).toBe(422);
    }
    const res = await createCard(list.id, { title: "C", description: "a".repeat(2001) });
    expect(res.status).toBe(422);
    expect(cards.length).toBe(0);
  });

  it("2000 文字 description は許可", async () => {
    const board = await createBoard();
    const list = await createList(board.id);
    const res = await createCard(list.id, { title: "C", description: "a".repeat(2000) });
    expect(res.status).toBe(201);
  });

  it("title と description の PATCH、フィールド無指定は 422", async () => {
    const board = await createBoard();
    const list = await createList(board.id);
    const created = await (await createCard(list.id, { title: "C" })).json();

    const patch1 = await cardPATCH(
      jsonReq(`http://localhost/api/cards/${created.id}`, { description: "d" }, "PATCH"),
      cardCtx(created.id),
    );
    expect(patch1.status).toBe(200);
    const body1 = await patch1.json();
    expect(body1.description).toBe("d");
    expect(body1.title).toBe("C");

    const patch2 = await cardPATCH(
      jsonReq(`http://localhost/api/cards/${created.id}`, {}, "PATCH"),
      cardCtx(created.id),
    );
    expect(patch2.status).toBe(422);
    expect((await patch2.json()).error.details).toEqual({ _root: "no_fields" });
  });

  it("存在しない listId の一覧は 404、削除後の PATCH は 404", async () => {
    const notFound = await cardsGET(
      bareReq("http://localhost/api/lists/none/cards"),
      listCtx("none"),
    );
    expect(notFound.status).toBe(404);

    const board = await createBoard();
    const list = await createList(board.id);
    const created = await (await createCard(list.id, { title: "C" })).json();
    const del = await cardDELETE(
      bareReq(`http://localhost/api/cards/${created.id}`, "DELETE"),
      cardCtx(created.id),
    );
    expect(del.status).toBe(200);
    const patch = await cardPATCH(
      jsonReq(`http://localhost/api/cards/${created.id}`, { title: "X" }, "PATCH"),
      cardCtx(created.id),
    );
    expect(patch.status).toBe(404);
  });
});
